// VendorLens knowledge base: Hong Kong rules, control library and supplier categories.
//
// Rule texts are SHORT PARAPHRASED SUMMARIES written for this prototype.
// They are not legal text and not legal advice; always check the source.

export const RULES = {
  SA2: { short: "HKMA SA-2 Outsourcing", name: "HKMA Supervisory Policy Manual SA-2: Outsourcing",
    summary: "Banks remain responsible for outsourced services. They must assess the risk, check the supplier's ability, have a proper contract, protect customer data, plan for disruption and exit, and keep audit access for themselves and the HKMA." },
  HKMA_AI: { short: "HKMA AI Principles", name: "HKMA High-level Principles on Artificial Intelligence (2019)",
    summary: "Banks using AI should keep senior management accountable, make AI explainable, use good-quality data, validate models before launch, monitor them over time, keep audit trails and carry out due diligence on AI vendors." },
  HKMA_CP: { short: "HKMA consumer protection (AI / GenAI)", name: "HKMA guidance on consumer protection in big data analytics and AI (2019) and generative AI (2024)",
    summary: "Customer-facing AI should treat customers fairly, be disclosed as AI, allow human intervention and review, and be tested for bias and unreliable output, with boards accountable for outcomes." },
  PDPO: { short: "PDPO", name: "Personal Data (Privacy) Ordinance (Cap. 486), Data Protection Principles 1–4",
    summary: "Personal data must be collected for a clear purpose and not excessively (DPP1), kept no longer than necessary (DPP2), not used for new purposes without consent (DPP3), and kept secure (DPP4)." },
  PCPD_AI: { short: "PCPD AI Framework", name: "PCPD Artificial Intelligence: Model Personal Data Protection Framework (2024)",
    summary: "Organisations buying or using AI should set AI governance, assess risks, keep human oversight in proportion to risk, manage AI suppliers by contract, minimise personal data, and prepare for AI incidents." },
};

